import { ZodString } from "./ZodString.ts";
import { ZodArray } from "./ZodArray.ts";
import { ZodRef } from "./ZodRef.ts";
import { ZodObject } from "./ZodObject.ts";
import { ZodUnion } from "./ZodUnion.ts";
import type { Modifiers, SchemaToValueFn, SchemaType } from 'jsr:@skmtc/core@0.28.3'
import { ZodNumber } from "./ZodNumber.ts";
import { ZodInteger } from "./ZodInteger.ts";
import { ZodBoolean } from "./ZodBoolean.ts";
import { ZodVoid } from "./ZodVoid.ts";
import { ZodUnknown } from "./ZodUnknown.ts";
import { toGeneratorOnlyKey, toRefName } from 'jsr:@skmtc/core@0.28.3'
import { zodEntry } from "./mod.ts";

/**
 * Maps a parsed schema node to its Zod snippet. Fine-grained attribution
 * is captured via each snippet's super call, which snapshots the schema's
 * `stackTrail` (`stackTrail: schema.stackTrail.clone()`) — no
 * router-level wrapper. The originating node is passed to every snippet,
 * including the ones that otherwise receive only decomposed parts
 * (`items` / `members` / `refName`) or nothing (`void` / `unknown`).
 */
export const toZodValue: SchemaToValueFn = ({
  schema: schemaNode,
  destinationPath,
  required,
  context,
  rootRef,
}) => {
  // `schemaNode` arrives typed as the generic `Schema` parameter, and TypeScript
  // does not narrow a type parameter by discriminant. Widening it to the
  // `SchemaType` union lets the switch below narrow each case on its own —
  // generator code narrows, it does not assert.
  const schema: SchemaType = schemaNode;

  const modifiers: Modifiers = {
    required,
    // description: 'description' in schema ? schema.description : undefined,
    nullable: "nullable" in schema ? schema.nullable : undefined,
  };

  const generatorKey = toGeneratorOnlyKey({ generatorId: zodEntry.id });

  switch (schema.type) {
    case "custom":
      return schema;
    case "ref":
      return new ZodRef({
        context,
        destinationPath,
        refName: toRefName(schema.$ref),
        modifiers,
        rootRef,
        schema,
      });
    case "array":
      return new ZodArray({
        context,
        destinationPath,
        modifiers,
        items: schema.items,
        generatorKey,
        rootRef,
        schema,
      });
    case "object":
      return new ZodObject({
        context,
        destinationPath,
        objectSchema: schema,
        modifiers,
        generatorKey,
        rootRef,
      });
    case "union":
      return new ZodUnion({
        context,
        destinationPath,
        members: schema.members,
        discriminator: schema.discriminator,
        modifiers,
        generatorKey,
        rootRef,
        schema,
      });
    case "number":
      return new ZodNumber({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "integer":
      return new ZodInteger({
        context,
        schema,
        modifiers,
        destinationPath,
        generatorKey,
      });
    case "boolean":
      return new ZodBoolean({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "void":
      return new ZodVoid({ context, destinationPath, generatorKey });
    case "string":
      return new ZodString({
        context,
        stringSchema: schema,
        modifiers,
        destinationPath,
        generatorKey,
      });
    case "unknown":
      return new ZodUnknown({ context, destinationPath, generatorKey, schema });
    default: {
      // Exhaustiveness check - if SchemaType is properly defined, this should never happen
      const _exhaustive: never = schema;
      throw new Error(`Unhandled schema type: ${_exhaustive}`);
    }
  }
};
import { TsSnippet, List } from 'jsr:@skmtc/lang-typescript@0.12.17'
import { applyModifiers } from "./applyModifiers.ts";
import type { GenerateContextType, GeneratorKey, Modifiers, OasString } from 'jsr:@skmtc/core@0.28.3'
import { ZodConstraint } from "./ZodConstraints.ts";

type ZodStringArgs = {
  context: GenerateContextType;
  stringSchema: OasString;
  modifiers: Modifiers;
  destinationPath: string;
  generatorKey: GeneratorKey;
};

export class ZodString extends TsSnippet {
  type = "string" as const;
  format: string | undefined;
  enums: string[] | (string | null)[] | undefined;
  constraints: List<ZodConstraint[]>;
  modifiers: Modifiers;
  constructor(
    { context, stringSchema, generatorKey, destinationPath, modifiers }:
      ZodStringArgs,
  ) {
    super({ context, generatorKey, stackTrail: stringSchema.stackTrail.clone() });

    this.enums = stringSchema.enums;
    this.format = stringSchema.format;
    this.constraints = new List<ZodConstraint[]>([], {
      skipEmpty: true,
      separator: "",
    });

    if (stringSchema.minLength) {
      this.constraints.values.push(
        new ZodConstraint({
          context,
          name: "min",
          value: stringSchema.minLength,
        }),
      );
    }

    if (stringSchema.maxLength) {
      this.constraints.values.push(
        new ZodConstraint({
          context,
          name: "max",
          value: stringSchema.maxLength,
        }),
      );
    }

    this.modifiers = modifiers;

    this.register({ imports: { zod: ["z"] }, destinationPath });
  }

  override toString(): string {
    const { enums } = this;

    let content: string;
    if (enums && Array.isArray(enums)) {
      content = enums.length === 1
        ? `z.literal("${enums[0]}")`
        : `z.enum([${enums.map((str) => `"${str}"`).join(", ")}])`;
    } else {
      content = `z.string()`;
    }

    return applyModifiers(`${content}${this.constraints}`, this.modifiers);
  }
}
import { isEmpty } from 'jsr:@skmtc/core@0.28.3'
import { TsSnippet, handleKey } from 'jsr:@skmtc/lang-typescript@0.12.17'
import type { CustomValue, GenerateContextType, GeneratorKey, Modifiers, OasObject, OasRef, OasSchema, RefName, TypeSystemObjectProperties, TypeSystemRecord, TypeSystemValue } from 'jsr:@skmtc/core@0.28.3'
import { toZodValue } from "./Zod.ts";
import { applyModifiers } from "./applyModifiers.ts";
import { ZodUnknown } from "./ZodUnknown.ts";

type ZodObjectProps = {
  context: GenerateContextType;
  destinationPath: string;
  objectSchema: OasObject;
  modifiers: Modifiers;
  generatorKey: GeneratorKey;
  rootRef?: RefName;
};

export class ZodObject extends TsSnippet {
  type = "object" as const;
  recordProperties: TypeSystemRecord | null;
  objectProperties: TypeSystemObjectProperties | null;
  modifiers: Modifiers;

  constructor({
    context,
    generatorKey,
    destinationPath,
    objectSchema,
    modifiers,
    rootRef,
  }: ZodObjectProps) {
    super({ context, generatorKey, stackTrail: objectSchema.stackTrail.clone() });

    this.modifiers = modifiers;

    const { properties, required, additionalProperties } = objectSchema;

    const hasProperties = properties && !isEmpty(properties);

    this.recordProperties = additionalProperties
      ? new ZodRecord({
        context,
        generatorKey,
        destinationPath,
        schema: additionalProperties,
        rootRef,
