  const modifiers: Modifiers = {
    required,
    // description: 'description' in schema ? schema.description : undefined,
    nullable: "nullable" in schema ? schema.nullable : undefined,
  };

  const generatorKey = toGeneratorOnlyKey({ generatorId: zodEntry.id });

  switch (schema.type) {
    case "custom":
      return schema;
    case "ref":
      return new ZodRef({
        context,
        destinationPath,
        refName: toRefName(schema.$ref),
        modifiers,
        rootRef,
        schema,
      });
    case "array":
      return new ZodArray({
        context,
        destinationPath,
        modifiers,
        items: schema.items,
        generatorKey,
        rootRef,
        schema,
      });
    case "object":
      return new ZodObject({
        context,
        destinationPath,
        objectSchema: schema,
        modifiers,
        generatorKey,
        rootRef,
      });
    case "union":
      return new ZodUnion({
        context,
        destinationPath,
        members: schema.members,
        discriminator: schema.discriminator,
        modifiers,
        generatorKey,
        rootRef,
        schema,
      });
    case "number":
      return new ZodNumber({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
      });
    case "integer":
      return new ZodInteger({
        context,
        schema,
        modifiers,
        destinationPath,
        generatorKey,
      });
    case "boolean":
      return new ZodBoolean({
        context,
        modifiers,
        schema,
        destinationPath,
        generatorKey,
